// ENG-2256 relation menu empty state + add flyout, driven with real CDP mouse/key input.
const D = "_verify/eng-2256-implement-new-relation-menu-empty-state";
const CANVAS = `${D}/relation-menu-canvas.md`;
const Q = "shape:verify-vqZxA";
const C = "shape:verify-bqu6_";
const E = "shape:verify-4dCoS";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export const prepare = async ({ client, json }, cam = { x: 150, y: 150, z: 0.8 }) => {
  await client.evaluate(`return (async () => {
    let leaf = app.workspace.getLeavesOfType("tldraw-dg-preview").find((l) => l.view.file?.path === ${json(CANVAS)});
    if (!leaf) {
      leaf = app.workspace.getLeaf("tab");
      await leaf.setViewState({ type: "tldraw-dg-preview", state: { file: ${json(CANVAS)} } });
    }
    app.workspace.setActiveLeaf(leaf, { focus: true });
    await new Promise((r) => setTimeout(r, 400));
    const el = leaf.view.containerEl.querySelector(".tl-canvas");
    const k = Object.keys(el).find((k) => k.startsWith("__reactFiber"));
    let f = el[k];
    while (f) { const v = f.memoizedProps?.value; if (v?.store && v.getCurrentPageShapes) { window.__dgEd = v; break; } f = f.return; }
    const ed = window.__dgEd;
    ed.deleteShapes(ed.getCurrentPageShapes().filter((s) => s.type === "discourse-relation").map((s) => s.id));
    // Deleting a pending arrow dismisses its menu, which reselects the source node in an effect.
    await new Promise((r) => setTimeout(r, 400));
    ed.selectNone();
    ed.setCamera(${json(cam)});
    if (!window.__dgToastHook) {
      window.__dgToastHook = true;
      document.addEventListener("show-toast", (e) => (window.__dgToasts ??= []).push(e.detail.description ?? e.detail.title));
    }
    window.__dgToasts = [];
    return true;
  })();`);
};

const mouse = (client, type, x, y, extra = {}) =>
  client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra });

const clickAt = async (client, { x, y }) => {
  await mouse(client, "mouseMoved", x, y, { button: "none" });
  await mouse(client, "mousePressed", x, y, { buttons: 1 });
  await mouse(client, "mouseReleased", x, y);
  await sleep(250);
};

// Select `from`, press on the drag dot nearest `to`, move in steps to `to`'s center, release.
export const dragRelation = async ({ client, json }, from, to) => {
  await client.evaluate(`window.__dgEd.select(${json(from)}); return true;`);
  await sleep(300);
  const sel = await client.evaluate(`return window.__dgEd.getSelectedShapeIds();`);
  if (sel.length !== 1 || sel[0] !== from) throw new Error(`expected ${from} selected, got ${sel}`);
  const pts = await client.evaluate(`
    const ed = window.__dgEd;
    const b = ed.getShapePageBounds(${json(to)});
    const target = ed.pageToScreen({ x: b.midX, y: b.midY });
    const dots = [...ed.getContainer().querySelectorAll(".cursor-crosshair")].map((d) => {
      const r = d.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    });
    dots.sort((a, c) => Math.hypot(a.x - target.x, a.y - target.y) - Math.hypot(c.x - target.x, c.y - target.y));
    return { start: dots[0], target, dotCount: dots.length };`);
  if (!pts.start) throw new Error("no drag handle dots rendered");
  const { start, target } = pts;
  await mouse(client, "mouseMoved", start.x, start.y, { button: "none" });
  await mouse(client, "mousePressed", start.x, start.y, { buttons: 1 });
  for (let i = 1; i <= 12; i++) {
    const t = i / 12;
    await mouse(client, "mouseMoved", start.x + (target.x - start.x) * t, start.y + (target.y - start.y) * t, { buttons: 1 });
    await sleep(20);
  }
  await mouse(client, "mouseReleased", target.x, target.y);
  await sleep(400);
  return pts;
};

// Snapshot of the menu, flyout, pending arrow and toasts.
export const observe = ({ client }) =>
  client.evaluate(`
    const ed = window.__dgEd;
    const header = [...document.querySelectorAll("span")].find((s) => s.textContent.trim().toLowerCase() === "relation type");
    const root = header?.closest(".z-30");
    const rect = (el) => { if (!el) return null; const r = el.getBoundingClientRect(); return { l: Math.round(r.left), t: Math.round(r.top), r: Math.round(r.right), b: Math.round(r.bottom), w: Math.round(r.width), h: Math.round(r.height) }; };
    const menu = root?.children[0];
    const flyout = root?.children[1] ?? null;
    const plus = root?.querySelector('[aria-label="Add relation type"]');
    const svg = plus?.querySelector("svg");
    const arrows = ed.getCurrentPageShapes().filter((s) => s.type === "discourse-relation");
    const a = arrows[0];
    const binds = a ? ed.getBindingsFromShape(a.id, "discourse-relation").map((b) => b.props.terminal + ":" + b.toId) : [];
    return {
      menuOpen: !!root,
      menuItems: menu ? [...menu.querySelectorAll(":scope > button")].map((b) => b.textContent.trim()) : [],
      plus: plus ? { expanded: plus.getAttribute("aria-expanded"), hasSvg: !!svg, svgClass: svg?.getAttribute("class"), svgRect: rect(svg), btnRect: rect(plus) } : null,
      headerRect: rect(header?.parentElement),
      menuRect: rect(menu),
      flyout: flyout ? { items: [...flyout.querySelectorAll("button")].map((b) => b.textContent.trim()), rect: rect(flyout) } : null,
      arrowCount: arrows.length,
      arrow: a ? { relationTypeId: a.props.relationTypeId, color: a.props.color, text: a.props.text, bindings: binds, relationInstanceId: a.meta?.relationInstanceId ?? null } : null,
      toasts: window.__dgToasts ?? [],
      selected: ed.getSelectedShapeIds(),
    };`);

const buttonCenter = ({ client, json }, label, where = "any") =>
  client.evaluate(`
    const header = [...document.querySelectorAll("span")].find((s) => s.textContent.trim().toLowerCase() === "relation type");
    const root = header?.closest(".z-30");
    const scope = ${json(where)} === "flyout" ? root?.children[1] : ${json(where)} === "menu" ? root?.children[0] : root;
    const btn = ${json(label)} === "+" ? root?.querySelector('[aria-label="Add relation type"]')
      : [...(scope?.querySelectorAll("button") ?? [])].find((b) => b.textContent.trim() === ${json(label)});
    if (!btn) return null;
    const r = btn.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);

export const clickButton = async (ctx, label, where) => {
  const p = await buttonCenter(ctx, label, where);
  if (!p) throw new Error(`button ${label} (${where}) not found`);
  await clickAt(ctx.client, p);
};

const ADD = ["Add existing…", "Create new"];
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const bothBound = (o) => o.arrow?.bindings.some((b) => b.startsWith("start:")) && o.arrow?.bindings.some((b) => b.startsWith("end:"));

export default [
  {
    name: "Empty pair opens menu with add actions",
    input: "drag from Question node dot to Claim node (no relation defined for Question-Claim)",
    expected: "menu opens with Add existing… / Create new, no + button, pending arrow kept and bound, no warning toast",
    run: async (ctx) => {
      await prepare(ctx);
      const pts = await dragRelation(ctx, Q, C);
      return { dots: pts.dotCount, ...(await observe(ctx)) };
    },
    expect: (o) => ({
      pass: o.menuOpen && same(o.menuItems, ADD) && !o.plus && o.arrowCount === 1 && bothBound(o) && o.toasts.length === 0,
      actual: `menu=${o.menuOpen} items=${o.menuItems.join("/")} plus=${!!o.plus} arrows=${o.arrowCount} bindings=${o.arrow?.bindings.length} toasts=[${o.toasts}] menu=${JSON.stringify(o.menuRect)}`,
    }),
  },
  {
    name: "Empty pair Add existing click keeps menu",
    input: "same drag; click Add existing…",
    expected: "menu stays open, arrow kept, no toast",
    run: async (ctx) => {
      await prepare(ctx);
      await dragRelation(ctx, Q, C);
      await clickButton(ctx, "Add existing…", "menu");
      await sleep(300);
      return observe(ctx);
    },
    expect: (o) => ({
      pass: o.menuOpen && same(o.menuItems, ADD) && o.arrowCount === 1 && o.toasts.length === 0,
      actual: `menu=${o.menuOpen} arrows=${o.arrowCount} toasts=[${o.toasts}]`,
    }),
  },
  {
    name: "Populated pair + toggles flyout",
    input: "drag Evidence to Claim; click +, click + again, click + a third time",
    expected: "header shows + with icon; flyout opens right of menu with both actions; second click closes; third reopens",
    run: async (ctx) => {
      await prepare(ctx, { x: -150, y: 150, z: 0.8 });
      await dragRelation(ctx, E, C);
      const initial = await observe(ctx);
      await clickButton(ctx, "+");
      const opened = await observe(ctx);
      await clickButton(ctx, "+");
      const closed = await observe(ctx);
      await clickButton(ctx, "+");
      const reopened = await observe(ctx);
      return { initial, opened, closed, reopened };
    },
    expect: ({ initial, opened, closed, reopened }) => {
      const f = opened.flyout;
      const aligned = f && f.rect.l >= opened.menuRect.r && f.rect.l - opened.menuRect.r <= 8 && Math.abs(f.rect.t - opened.menuRect.t) <= 2;
      const pass = initial.menuOpen && initial.menuItems.length > 0 && !initial.menuItems.includes("Add existing…") &&
        initial.plus?.hasSvg && initial.plus.expanded === "false" && !initial.flyout &&
        f && same(f.items, ADD) && opened.plus.expanded === "true" && aligned &&
        !closed.flyout && closed.menuOpen && closed.plus.expanded === "false" &&
        !!reopened.flyout && reopened.arrowCount === 1;
      return {
        pass,
        actual: `items=${initial.menuItems.join("/")} plusSvg=${initial.plus?.hasSvg} svg=${JSON.stringify(initial.plus?.svgRect)} btn=${JSON.stringify(initial.plus?.btnRect)} header=${JSON.stringify(initial.headerRect)}; open: flyout=${f?.items.join("/")} menu=${JSON.stringify(opened.menuRect)} fly=${JSON.stringify(f?.rect)} aligned=${aligned}; 2nd click flyout=${!!closed.flyout}; 3rd=${!!reopened.flyout}`,
      };
    },
  },
  {
    name: "Flyout item click keeps menu; Escape closes flyout only",
    input: "Evidence to Claim; + ; click flyout Create new; press Escape once",
    expected: "after click menu+flyout stay; after Escape flyout gone, menu and arrow stay",
    run: async (ctx) => {
      await prepare(ctx, { x: -150, y: 150, z: 0.8 });
      await dragRelation(ctx, E, C);
      await clickButton(ctx, "+");
      await clickButton(ctx, "Create new", "flyout");
      const afterClick = await observe(ctx);
      await ctx.client.pressEscape();
      await sleep(300);
      const afterEsc = await observe(ctx);
      return { afterClick, afterEsc };
    },
    expect: ({ afterClick: a, afterEsc: b }) => ({
      pass: a.menuOpen && !!a.flyout && a.arrowCount === 1 && b.menuOpen && !b.flyout && b.arrowCount === 1 && b.plus?.expanded === "false",
      actual: `after click menu=${a.menuOpen} flyout=${!!a.flyout} arrows=${a.arrowCount}; after Esc menu=${b.menuOpen} flyout=${!!b.flyout} arrows=${b.arrowCount}`,
    }),
  },
  {
    name: "Second Escape dismisses menu and deletes arrow",
    input: "Evidence to Claim; + ; Escape; Escape",
    expected: "menu gone, pending arrow deleted, source node reselected",
    run: async (ctx) => {
      await prepare(ctx, { x: -150, y: 150, z: 0.8 });
      await dragRelation(ctx, E, C);
      await clickButton(ctx, "+");
      await ctx.client.pressEscape();
      await sleep(250);
      const mid = await observe(ctx);
      await ctx.client.pressEscape();
      await sleep(300);
      return { mid, end: await observe(ctx) };
    },
    expect: ({ mid, end }) => ({
      pass: mid.menuOpen && !mid.flyout && !end.menuOpen && end.arrowCount === 0,
      actual: `1st Esc menu=${mid.menuOpen} flyout=${!!mid.flyout}; 2nd Esc menu=${end.menuOpen} arrows=${end.arrowCount} selected=${end.selected}`,
    }),
  },
  {
    name: "Picking a relation type creates the relation",
    input: "Evidence to Claim; click 'supports'",
    expected: "menu closes; arrow keeps relationTypeId + color; Relation Created toast; relations.json gains an entry",
    setup: async ({ client }) => ({
      relations: await client.evaluate(`return app.vault.read(app.vault.getAbstractFileByPath("relations.json"));`),
    }),
    run: async (ctx, state) => {
      await prepare(ctx, { x: -150, y: 150, z: 0.8 });
      await dragRelation(ctx, E, C);
      const labels = (await observe(ctx)).menuItems;
      await clickButton(ctx, "supports", "menu");
      await ctx.client.waitFor(`(window.__dgToasts ?? []).length > 0`, { timeout: 5000, label: "toast" }).catch(() => {});
      await sleep(500);
      const o = await observe(ctx);
      const relLen = await ctx.client.evaluate(`return app.vault.read(app.vault.getAbstractFileByPath("relations.json")).then((t) => Object.keys(JSON.parse(t).relations ?? {}).length);`);
      const before = Object.keys(JSON.parse(state.relations).relations ?? {}).length;
      return { labels, before, after: relLen, ...o };
    },
    expect: (o) => ({
      pass: !o.menuOpen && o.arrowCount === 1 && !!o.arrow.relationTypeId && o.arrow.color === "green" &&
        o.toasts.some((t) => /Added supports relation/.test(t)) && o.after === o.before + 1,
      actual: `labels=${o.labels.join("/")} menu=${o.menuOpen} type=${o.arrow?.relationTypeId} color=${o.arrow?.color} text=${o.arrow?.text} instance=${o.arrow?.relationInstanceId} toasts=[${o.toasts}] relations ${o.before}->${o.after}`,
    }),
    teardown: async ({ client, json }, state) => {
      await client.evaluate(`const ed = window.__dgEd; ed.deleteShapes(ed.getCurrentPageShapes().filter((s) => s.type === "discourse-relation").map((s) => s.id)); return true;`);
      if (state?.relations) await client.evaluate(`return app.vault.modify(app.vault.getAbstractFileByPath("relations.json"), ${json(state.relations)}).then(() => true);`);
    },
  },
  {
    name: "Click outside dismisses menu and deletes arrow",
    input: "Evidence to Claim; click empty canvas",
    expected: "menu gone, pending arrow deleted",
    run: async (ctx) => {
      await prepare(ctx, { x: -150, y: 150, z: 0.8 });
      await dragRelation(ctx, E, C);
      const before = await observe(ctx);
      const p = await ctx.client.evaluate(`const s = window.__dgEd.pageToScreen({ x: 150, y: 450 }); return { x: s.x, y: s.y };`);
      await clickAt(ctx.client, p);
      await sleep(300);
      return { before, after: await observe(ctx) };
    },
    expect: ({ before, after }) => ({
      pass: before.menuOpen && before.arrowCount === 1 && !after.menuOpen && after.arrowCount === 0,
      actual: `before menu=${before.menuOpen} arrows=${before.arrowCount}; after menu=${after.menuOpen} arrows=${after.arrowCount}`,
    }),
  },
  {
    name: "Missing node type removes arrow with toast",
    input: "clear Question shape's nodeTypeId; drag Question to Claim",
    expected: "no menu, arrow removed, toast 'Both nodes need a node type to create a relation'",
    run: async (ctx) => {
