      await clickEl(ctx, `return ${ROW}?.querySelector(".relative.min-w-32 > button");`);
      const colours = await ctx.client.evaluate(`return ${ROW}.querySelectorAll(".relative.min-w-32 > div button").length;`);
      await clickEl(ctx, `return ${ROW}?.querySelector(".relative.min-w-32 > button");`);
