      };
    },
    teardown: restore,
  },
  {
    name: "Dialog clicks, Escape, Cancel and backdrop keep the menu and arrow",
    input: "Question → Claim; Create new; click inside the dialog, Escape; Create new, Cancel; Create new, click the backdrop; then Escape once more",
    expected: "each way of closing the dialog leaves the menu and pending arrow; the next Escape dismisses the menu and deletes the arrow",
    run: async (ctx) => {
      await prepare(ctx);
