      const error = await ctx.client.evaluate(`return [...document.querySelectorAll(".discourse-relation-types .text-error")].map((e) => e.textContent.trim());`);
      const unchanged = before === (await ctx.client.evaluate(`return JSON.stringify(${P(ctx)}.settings.relationTypes);`));
      return { row, colours, error, unchanged };
    },
    expect: (o) => ({
      pass: o.row?.color === "Blue" && o.colours === 13 && o.error.filter((e) => e === 'Duplicate label "supports"').length === 2 && o.unchanged,
      actual: `row=${JSON.stringify(o.row)} colours=${o.colours} errors=[${o.error}] settingsUnchanged=${o.unchanged}`,
    }),
    teardown: async (ctx, state) => {
      await ctx.client.evaluate(`app.setting.close(); return true;`);
      await restore(ctx, state);
    },
  },
];

