S=/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/02d290a9-42bf-4dee-8cac-dbcfdcfb7d45/scratchpad/eng2258; python3 - "$S/scenarios.mjs" <<'EOF'
import sys
p=sys.argv[1]; s=open(p).read()
new = r'''  {
    name: "Type added while the dialog is open is caught as a duplicate",
    input: "Question → Claim; Create new; another type 'v2258 concurrent' is saved to settings meanwhile; submit 'v2258 concurrent'",
    expected: "'Duplicate label \"v2258 concurrent\"'; dialog stays open; only one type with that label in settings",
    setup: snapshot,
    run: async (ctx) => {
      await prepare(ctx);
      await dragRelation(ctx, Q, C);
      await openDialog(ctx, "menu");
      await ctx.client.evaluate(`const p = ${P(ctx)}; const now = Date.now();
        p.settings.relationTypes = [...p.settings.relationTypes, { id: "rel_verify2258", label: "v2258 concurrent", complement: "v2258 concurrent of", color: "red", created: now, modified: now }];
        return p.saveSettings().then(() => true);`);
      await fillDialog(ctx, { label: "v2258 concurrent", complement: COMPLEMENT });
      await clickDialogButton(ctx, "Continue");
      await sleep(400);
      const d = await dialog(ctx);
      const count = await ctx.client.evaluate(`return ${P(ctx)}.settings.relationTypes.filter((rt) => rt.label === "v2258 concurrent").length;`);
      return { d, count };
    },
    expect: (o) => ({
      pass: o.d.open && o.d.error === 'Duplicate label "v2258 concurrent"' && o.count === 1,
      actual: `dialog=${o.d.open} error=${o.d.error} types with that label=${o.count}`,
    }),
    teardown: restore,
  },
  {
    name: "Escape and backdrop during a pending save don't close the dialog",
    input: `Question → Claim; Create new "${LABEL}"; saveSettings slowed to 1.5s; Continue, then Escape and a backdrop click while saving`,
    expected: "dialog stays open during the save, then closes; menu lists the new type; both toasts",
    setup: snapshot,
    run: async (ctx) => {
      await prepare(ctx);
      await dragRelation(ctx, Q, C);
      await openDialog(ctx, "menu");
      await fillDialog(ctx, { label: LABEL, complement: COMPLEMENT });
      await ctx.client.evaluate(`const p = ${P(ctx)}; window.__dgOrigSave = p.saveSettings; p.saveSettings = function (...a) { return new Promise((r) => setTimeout(r, 1500)).then(() => window.__dgOrigSave.apply(p, a)); }; return true;`);
      const bg = await ctx.client.evaluate(`const r = ${DIALOG}.querySelector(".modal").getBoundingClientRect(); return { x: Math.max(5, r.left - 40), y: r.top + 20 };`);
      await clickDialogButton(ctx, "Continue");
      await ctx.client.pressEscape();
      await sleep(150);
      await clickAt(ctx.client, bg);
      const during = await dialog(ctx);
      const menuDuring = await observe(ctx);
      await ctx.client.waitFor(`!${DIALOG}`, { timeout: 5000, label: "dialog closed after save" }).catch(() => {});
      await sleep(400);
      return { during, menuDuring, after: await observe(ctx), dialogAfter: await dialog(ctx) };
    },
    expect: (o) => ({
      pass: o.during.open && o.menuDuring.menuOpen && o.menuDuring.arrowCount === 1 && !o.dialogAfter.open &&
        o.after.menuItems.includes(LABEL) && o.after.toasts.includes("Relation type created"),
      actual: `during save: dialog=${o.during.open} menu=${o.menuDuring.menuOpen} arrows=${o.menuDuring.arrowCount}; after: dialog=${o.dialogAfter.open} menu=[${o.after.menuItems}] toasts=[${o.after.toasts}]`,
    }),
    teardown: async (ctx, state) => {
      await ctx.client.evaluate(`const p = ${P(ctx)}; if (window.__dgOrigSave) { p.saveSettings = window.__dgOrigSave; delete window.__dgOrigSave; } return true;`);
      await restore(ctx, state);
    },
  },
];
'''
i=s.rindex('];')
s=s[:i]+new.lstrip('\n').replace('\n];\n','\n];\n',1)
# remove duplicated closing: new already ends with '];'
open(p,'w').write(s)
EOF
